package com.vynedam.stockai.service;
import com.vynedam.stockai.domain.BatchStatus; import com.vynedam.stockai.repository.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class DashboardService { private final BatchRepository batches; private final MaterialRepository materials; public DashboardService(BatchRepository b,MaterialRepository m){batches=b;materials=m;} public Map<String,Object> summary(){var available=batches.findByStatus(BatchStatus.AVAILABLE);double quantity=available.stream().mapToDouble(x->x.quantity).sum();var totals=new HashMap<String,Double>();batches.findAll().forEach(b->totals.merge(b.materialId,b.quantity,Double::sum));var low=materials.findAll().stream().filter(m->totals.getOrDefault(m.id,0d)<=m.reorderPoint).toList();return Map.of("availableStock",Map.of("quantity",quantity,"batches",available.size()),"lowStock",low,"quarantineBatches",batches.findByStatus(BatchStatus.QUARANTINE).size());} }
